// Office files written directly: PowerPoint (.pptx) with a picture per slide and speaker notes,
// and Word (.docx) for transcripts. No Microsoft Office needed.

import Foundation
import AppKit

enum Office {
    static func xml(_ s: String) -> String {
        let escaped = s.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;").replacingOccurrences(of: "\"", with: "&quot;")
        var v = String.UnicodeScalarView()
        v.append(contentsOf: escaped.unicodeScalars.filter { $0.value == 9 || $0.value == 10 || $0.value == 13 || $0.value >= 32 })
        return String(v)
    }

    /// Zips a folder's contents (not the folder itself) into an Office file.
    static func zip(_ folder: URL, to out: URL) throws {
        try? FileManager.default.removeItem(at: out)
        let p = Process()
        p.executableURL = URL(fileURLWithPath: "/usr/bin/zip")
        p.arguments = ["-q", "-r", "-X", out.path, "."]
        p.currentDirectoryURL = folder
        try p.run()
        p.waitUntilExit()
        guard p.terminationStatus == 0 else { throw PGError("Couldn't write \(out.lastPathComponent).") }
    }

    static func tempDir() throws -> URL {
        let d = FileManager.default.temporaryDirectory.appendingPathComponent("PareStudioOffice-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: d, withIntermediateDirectories: true)
        return d
    }

    // MARK: PowerPoint

    /// One slide per image, each picture fitted to a 16:9 slide on black. notes[i] becomes slide i's speaker notes.
    static func pptx(images: [URL], notes: [[String]], to out: URL) throws {
        guard !images.isEmpty else { throw PGError("There are no slides to save.") }
        let fm = FileManager.default
        let d = try tempDir()
        defer { try? fm.removeItem(at: d) }
        let tz = d.appendingPathComponent("t.zip")
        guard let data = Data(base64Encoded: template) else { throw PGError("PowerPoint template is damaged.") }
        try data.write(to: tz)
        let root = d.appendingPathComponent("p")
        guard Tools.runQuick("/usr/bin/ditto", ["-x", "-k", tz.path, root.path]) == 0 else { throw PGError("Couldn't prepare the PowerPoint file.") }
        for sub in ["ppt/media", "ppt/slides/_rels", "ppt/notesSlides/_rels"] {
            try fm.createDirectory(at: root.appendingPathComponent(sub), withIntermediateDirectories: true)
        }
        let W = 12192000.0, H = 6858000.0
        var ids = "", rels = "", overrides = ""
        for (k, img) in images.enumerated() {
            let i = k + 1
            // Always PNG inside the file.
            guard let ns = NSImage(contentsOf: img), let tiff = ns.tiffRepresentation,
                  let rep = NSBitmapImageRep(data: tiff), let png = rep.representation(using: .png, properties: [:]) else {
                throw PGError("Couldn't read slide image \(img.lastPathComponent).")
            }
            try png.write(to: root.appendingPathComponent("ppt/media/image\(i).png"))
            let iw = Double(max(1, rep.pixelsWide)), ih = Double(max(1, rep.pixelsHigh))
            let s = min(W / iw, H / ih)
            let cx = Int(iw * s), cy = Int(ih * s), x = (Int(W) - cx) / 2, y = (Int(H) - cy) / 2
            let slide = """
            <?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><p:cSld><p:bg><p:bgPr><a:solidFill><a:srgbClr val="000000"/></a:solidFill><a:effectLst/></p:bgPr></p:bg><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/><p:pic><p:nvPicPr><p:cNvPr id="2" name="Slide \(i)"/><p:cNvPicPr><a:picLocks noChangeAspect="1"/></p:cNvPicPr><p:nvPr/></p:nvPicPr><p:blipFill><a:blip r:embed="rId2"/><a:stretch><a:fillRect/></a:stretch></p:blipFill><p:spPr><a:xfrm><a:off x="\(x)" y="\(y)"/><a:ext cx="\(cx)" cy="\(cy)"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr></p:pic></p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>
            """
            try slide.write(to: root.appendingPathComponent("ppt/slides/slide\(i).xml"), atomically: true, encoding: .utf8)
            let srels = """
            <?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout7.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/image\(i).png"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/notesSlide" Target="../notesSlides/notesSlide\(i).xml"/></Relationships>
            """
            try srels.write(to: root.appendingPathComponent("ppt/slides/_rels/slide\(i).xml.rels"), atomically: true, encoding: .utf8)
            let lines = k < notes.count && !notes[k].isEmpty ? notes[k] : [""]
            let paras = lines.map { "<a:p><a:r><a:rPr lang=\"en-AU\" dirty=\"0\"/><a:t>\(xml($0))</a:t></a:r></a:p>" }.joined()
            let note = """
            <?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:notes xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/><p:sp><p:nvSpPr><p:cNvPr id="2" name="Slide Image Placeholder 1"/><p:cNvSpPr><a:spLocks noGrp="1" noRot="1" noChangeAspect="1"/></p:cNvSpPr><p:nvPr><p:ph type="sldImg"/></p:nvPr></p:nvSpPr><p:spPr/></p:sp><p:sp><p:nvSpPr><p:cNvPr id="3" name="Notes Placeholder 2"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="body" idx="1"/></p:nvPr></p:nvSpPr><p:spPr/><p:txBody><a:bodyPr/><a:lstStyle/>\(paras)</p:txBody></p:sp></p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:notes>
            """
            try note.write(to: root.appendingPathComponent("ppt/notesSlides/notesSlide\(i).xml"), atomically: true, encoding: .utf8)
            let nrels = """
            <?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/notesMaster" Target="../notesMasters/notesMaster1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" Target="../slides/slide\(i).xml"/></Relationships>
            """
            try nrels.write(to: root.appendingPathComponent("ppt/notesSlides/_rels/notesSlide\(i).xml.rels"), atomically: true, encoding: .utf8)
            ids += "<p:sldId id=\"\(255 + i)\" r:id=\"rId\(100 + i)\"/>"
            rels += "<Relationship Id=\"rId\(100 + i)\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide\" Target=\"slides/slide\(i).xml\"/>"
            overrides += "<Override PartName=\"/ppt/slides/slide\(i).xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.slide+xml\"/><Override PartName=\"/ppt/notesSlides/notesSlide\(i).xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.notesSlide+xml\"/>"
        }
        for (file, key, value) in [("ppt/presentation.xml", "{{SLIDES}}", ids),
                                   ("ppt/_rels/presentation.xml.rels", "{{SLIDERELS}}", rels),
                                   ("[Content_Types].xml", "{{OVERRIDES}}", overrides)] {
            let u = root.appendingPathComponent(file)
            let s = try String(contentsOf: u, encoding: .utf8).replacingOccurrences(of: key, with: value)
            try s.write(to: u, atomically: true, encoding: .utf8)
        }
        try zip(root, to: out)
    }

    // MARK: Word

    /// A simple Word document: a title, then one paragraph per entry. Entries can start with a bold time.
    static func docx(title: String, paragraphs: [(time: String?, text: String)], to out: URL) throws {
        let fm = FileManager.default
        let d = try tempDir()
        defer { try? fm.removeItem(at: d) }
        try fm.createDirectory(at: d.appendingPathComponent("_rels"), withIntermediateDirectories: true)
        try fm.createDirectory(at: d.appendingPathComponent("word"), withIntermediateDirectories: true)
        let types = """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>
        """
        let rels = """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>
        """
        func run(_ t: String, bold: Bool = false, size: Int? = nil, colour: String? = nil) -> String {
            var pr = ""
            if bold { pr += "<w:b/>" }
            if let colour { pr += "<w:color w:val=\"\(colour)\"/>" }
            if let size { pr += "<w:sz w:val=\"\(size)\"/>" }
            return "<w:r>\(pr.isEmpty ? "" : "<w:rPr>\(pr)</w:rPr>")<w:t xml:space=\"preserve\">\(xml(t))</w:t></w:r>"
        }
        var body = "<w:p><w:pPr><w:spacing w:after=\"240\"/></w:pPr>\(run(title, bold: true, size: 36))</w:p>"
        for p in paragraphs {
            body += "<w:p><w:pPr><w:spacing w:after=\"120\"/></w:pPr>"
            if let t = p.time { body += run(t + "  ", bold: true, colour: "6B7280") }
            body += run(p.text) + "</w:p>"
        }
        let doc = """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>\(body)<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134" w:header="708" w:footer="708" w:gutter="0"/></w:sectPr></w:body></w:document>
        """
        try types.write(to: d.appendingPathComponent("[Content_Types].xml"), atomically: true, encoding: .utf8)
        try rels.write(to: d.appendingPathComponent("_rels/.rels"), atomically: true, encoding: .utf8)
        try doc.write(to: d.appendingPathComponent("word/document.xml"), atomically: true, encoding: .utf8)
        try zip(d, to: out)
    }

    /// A blank 16:9 PowerPoint (themes, master, layouts and notes master), with placeholders for the slides.
    static let template = ""
}
